import React, { useState, useRef, useEffect, useLayoutEffect, useCallback } from 'react';
import { ARCHIVE_GARMENTS } from '../data/garments';
import { ChevronLeft, ChevronRight, Pause, Play } from 'lucide-react';
import { ApprovedGarmentMotion } from './ApprovedGarmentMotion';
import { archiveClickIntent, archiveLayout } from './archive-layout';
import './garment-carousel.css';

// Embedded optimized concept backdrop: reliable in AI Studio without another asset upload.
const ARCHIVE_LANDSCAPE_DATA = 'data:image/jpeg;base64,';

interface ArchiveSectionProps {
  onOpenGarment?: (garmentId: string) => void;
  initialGarmentId?: string;
  onSelectGarmentForStudio?: (garmentId: string) => void;
  onInspectGarment?: (garment: any) => void;
}

export const ArchiveSection: React.FC<ArchiveSectionProps> = ({ onOpenGarment, initialGarmentId }) => {
  const count = ARCHIVE_GARMENTS.length;
  const [selectedIndex, setSelectedIndex] = useState(() => Math.max(0, ARCHIVE_GARMENTS.findIndex(g => g.id === initialGarmentId)));
  const [paused, setPaused] = useState(() => window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  const [size, setSize] = useState({ width: 1000, height: 600 });
  const archiveRef = useRef<HTMLElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const previousOffsets = useRef<Record<string, number>>({});
  const gesture = useRef<{ x: number; y: number; index: number | null } | null>(null);
  const select = useCallback((index: number) => setSelectedIndex((index + count) % count), [count]);
  const previous = () => select(selectedIndex - 1);
  const next = () => select(selectedIndex + 1);
  const activate = (index: number) => {
    if (archiveClickIntent(index, selectedIndex) === 'open') onOpenGarment?.(ARCHIVE_GARMENTS[index].id);
    else select(index);
  };

  useLayoutEffect(() => {
    // Tab changes must start at the top; don't leave the collars under the sticky navbar.
    window.scrollTo({ top: 0, behavior: 'instant' });
    const archive = archiveRef.current;
    if (!archive) return;
    const update = () => {
      // Reserve real navbar/banner space, including the AI Studio iframe viewport.
      const top = archive.getBoundingClientRect().top + window.scrollY;
      archive.style.setProperty('--archive-available-height', `${Math.max(280, window.innerHeight - top)}px`);
    };
    update();
    const observer = new ResizeObserver(update);
    const main = archive.parentElement;
    Array.from(main?.parentElement?.children ?? []).forEach(sibling => {
      if (sibling !== main) observer.observe(sibling);
    });
    window.addEventListener('resize', update);
    return () => { observer.disconnect(); window.removeEventListener('resize', update); };
  }, []);

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const update = () => setSize({ width: stage.clientWidth, height: stage.clientHeight });
    update();
    const observer = new ResizeObserver(update); observer.observe(stage);
    return () => observer.disconnect();
  }, []);
  useEffect(() => {
    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setPaused(media.matches);
    media.addEventListener('change', update);
    return () => media.removeEventListener('change', update);
  }, []);
  const offsetFor = (index: number) => {
    let offset = index - selectedIndex;
    if (offset > count / 2) offset -= count;
    if (offset < -count / 2) offset += count;
    return offset;
  };
  useEffect(() => {
    ARCHIVE_GARMENTS.forEach((garment, index) => { previousOffsets.current[garment.id] = offsetFor(index); });
  }, [selectedIndex]);

  const { specimenWidth, neighborScale, step } = archiveLayout(size.width, size.height);

  return (
    <section ref={archiveRef} className="garment-archive" aria-label="Kho Việt phục">
      <img className="archive-scenery" src={ARCHIVE_LANDSCAPE_DATA} alt="" aria-hidden="true" draggable="false" />
      <div className="archive-scenery-wash" aria-hidden="true" />
      <svg className="archive-water-lines" viewBox="0 0 1600 900" preserveAspectRatio="none" aria-hidden="true" focusable="false">
        <g fill="none" stroke="#6f8c87" strokeWidth="1.2" opacity=".18">
          <path d="M-80 738 Q205 668 470 738 T1030 735 T1680 714" />
          <path d="M-80 759 Q205 691 470 759 T1030 756 T1680 735" />
          <path d="M-80 780 Q205 714 470 780 T1030 777 T1680 756" />
          <path d="M-80 805 Q205 741 470 805 T1030 802 T1680 781" />
          <path d="M-80 830 Q205 768 470 830 T1030 827 T1680 806" />
          <path d="M-80 855 Q205 795 470 855 T1030 852 T1680 831" />
        </g>
      </svg>
      <header className="garment-archive__heading">
        <h1>Kho Việt phục</h1>
        <button type="button" onClick={() => setPaused(value => !value)} aria-pressed={paused}
          aria-label={paused ? 'Bật chuyển động vải cho các trang phục' : 'Tạm dừng chuyển động vải cho các trang phục'}>
          {paused ? <Play size={16} /> : <Pause size={16} />}<span>{paused ? 'Chuyển động' : 'Tạm dừng'}</span>
        </button>
      </header>
      <div className="garment-archive__display">
        <button className="garment-chevron garment-chevron--left" type="button" onClick={previous} aria-label="Trang phục trước"><ChevronLeft /></button>
        <div className="garment-stage" ref={stageRef} tabIndex={0} aria-roledescription="carousel" aria-label="Bảy phom trang phục"
          onKeyDown={event => {
            if (event.key === 'ArrowLeft') { event.preventDefault(); previous(); }
            if (event.key === 'ArrowRight') { event.preventDefault(); next(); }
          }}
          onPointerDown={event => {
            if (event.button !== 0 || !event.isPrimary) return;
            const item = (event.target as HTMLElement).closest<HTMLElement>('[data-garment-index]');
            gesture.current = { x: event.clientX, y: event.clientY, index: item ? Number(item.dataset.garmentIndex) : null };
            event.currentTarget.setPointerCapture(event.pointerId);
          }}
          onPointerCancel={() => { gesture.current = null; }}
          onPointerUp={event => {
            const start = gesture.current; gesture.current = null;
            if (!start) return;
            const dx = event.clientX - start.x, dy = event.clientY - start.y;
            if (Math.abs(dx) > 35 && Math.abs(dx) > Math.abs(dy)) dx < 0 ? next() : previous();
            else if (Math.hypot(dx, dy) < 8 && start.index !== null) activate(start.index);
          }}>
          {ARCHIVE_GARMENTS.map((garment, index) => {
            const offset = offsetFor(index), selected = offset === 0, visible = Math.abs(offset) <= 1;
            const prior = previousOffsets.current[garment.id];
            const wrap = prior !== undefined && Math.abs(prior - offset) > count / 2;
            // Off-stage items stop drawing; selected/unselected use one renderer.
            return (
              <button key={garment.id} data-garment-index={index} type="button" className="garment-specimen"
                aria-label={`${selected ? 'Mở hồ sơ' : 'Chọn'} ${garment.name}`} aria-current={selected ? 'true' : undefined} aria-hidden={!visible} tabIndex={visible ? 0 : -1}
                onClick={event => { if (event.detail === 0) activate(index); }}
                style={{ left: `calc(50% + ${offset * step}px)`, width: specimenWidth,
                  transform: `translate(-50%, -50%) scale(${selected ? 1 : neighborScale})`,
                  zIndex: selected ? 20 : 10, opacity: visible ? selected ? 1 : .86 : 0,
                  filter: selected ? 'none' : 'grayscale(1)', pointerEvents: visible ? 'auto' : 'none',
                  transition: wrap ? 'none' : undefined }}>
                <ApprovedGarmentMotion garmentId={garment.id} name={garment.name} paused={paused} active={visible} />
              </button>
            );
          })}
        </div>
        <button className="garment-chevron garment-chevron--right" type="button" onClick={next} aria-label="Trang phục tiếp theo"><ChevronRight /></button>
      </div>
      <div className="carousel-caption" aria-live="polite" aria-atomic="true"><h2>{ARCHIVE_GARMENTS[selectedIndex].name}</h2></div>
    </section>
  );
};
